function authSections(p){const sign=p.kind==='signin'||p.kind==='partner-access',register=p.kind==='register',forgot=p.kind==='forgot';return [S('Access purpose & form',`<div class="auth"><div class="auth-story"><span class="eyebrow">${p.kind==='partner-access'?'FOR TRAVEL PARTNERS':'YOUR TRIP LINE ACCOUNT'}</span><h1>${p.kind==='partner-access'?'A connected workspace.':'Your journeys.<br>In one place.'}</h1><p>${p.kind==='partner-access'?'Dedicated access for approved organizations and their teams.':'Access reservation details and keep your contact preferences up to date.'}</p></div><div class="auth-form"><span class="eyebrow">TRIP LINE</span><h2>${p.name}</h2><form class="form">${register?'<label>Full name<input autocomplete="name" required></label>':''}${p.kind!=='reset'?'<label>Email<input type="email" autocomplete="email" required></label>':''}${!forgot?`<label>${p.kind==='reset'?'New password':'Password'}<input type="password" autocomplete="${sign?'current-password':'new-password'}" required></label>`:''}${register||p.kind==='reset'?'<label>Confirm password<input type="password" autocomplete="new-password" required></label>':''}${register?'<label class="check"><input type="checkbox" required><span>I have read the account terms and privacy notice.</span></label>':''}<button class="submit">${forgot?'Send recovery link':p.kind==='reset'?'Update password':register?'Create account':'Sign in'}</button><p class="form-message" role="status"></p></form><div class="actions">${sign?link('Forgot password','forgot'):link('Back to sign-in','signin')}${p.kind==='signin'?link('Create account','register'):''}</div>${p.kind==='partner-access'?`<p>Need partner access? ${link('Contact the team')}</p>`:''}</div></div>`,'Two-column access: restrained brand story and focused form. No decorative 3D.','Short purpose band above full-width form; password fields, errors and recovery remain visible.'),S('Access error & recovery states',`<div class="reading"><h2>Clear feedback.</h2><p class="notice">Invalid credentials: “We couldn’t sign you in. Check your details and try again.”</p><p class="notice">Recovery: “If an account exists for that email, we’ll send the next steps.”</p><p class="notice">Expired reset link: request a new link.</p></div>`,'Inline errors and safe recovery confirmation; no account-existence disclosure.','Errors beside relevant fields; stable layout and keyboard access.','paper')];}
