function reservationRecord(partner){return [S('Status, reference & itinerary',`<span class="badge">Supplier status</span><h2>Reservation reference</h2>${['Destination & selected option','Travel dates & travelers','Payment status','Supplier reference'].map(t=>`<div class="status-line"><strong>${t}</strong><span>Verified reservation data</span></div>`).join('')}`,'Status and exact reservation data, no invented confirmed record.','Status/reference above itinerary and contacts.'),S('Conditions, documents & support',`<div class="booking-grid"><div><h2>Manage your journey.</h2><div class="faq"><details><summary>Conditions</summary><p>Confirmed supplier terms and applicable cancellation details.</p></details><details><summary>Documents</summary><p>Available vouchers or tickets, if provided.</p></details></div>${link('Request help')}</div>${summary()}</div>`,'Documents and supported management actions only; cancellation/change paths depend on API.','Stack conditions and available documents; support easy to reach.'),S(partner?'Organization reference & audit':'Reservation activity',`<h2>${partner?'Team coordination.':'Reservation updates.'}</h2><div class="status-line"><strong>Latest update</strong><span>Timestamp and supplier event</span></div>${partner?'<div class="status-line"><strong>Client reference</strong><span>Internal reference, if supported</span></div>':''}`,'Timestamped status history; partner attribution where available.','Compact chronological entries, no dense audit table.')];}
function partnerSections(p){let a=[S('Workspace heading',`<span class="eyebrow">PARTNER WORKSPACE</span><h1>${p.name}</h1>`,'Organization context and workspace navigation.','Compact organization header; scrollable primary navigation.')];if(p.kind==='partner-overview')a.push(S('Operational overview',`<h2>What needs your attention?</h2><div class="empty"><h3>No reservations to review.</h3><p>Pending actions and reservation records appear here when available.</p>${link('Start a search','partner-search')}</div>`,'Pending actions and recent records; no invented revenue charts or wallet.','Attention items first, then search and recent activity.'),S('Workspace shortcuts',`<div class="status-line">${link('Reservations','partner-reservations')}${link('Organization settings','partner-settings')}</div>`,'Direct workspace utilities.','Simple stacked navigation.'));else if(p.kind==='partner-search')a.push(S('Client reservation criteria',searchForm(true),'Search plus optional organization/client reference. Supported B2B inventory only.','Single-column criteria; client reference below travel essentials.'),S('Results & onward flow',`<p>Result details, supplier conditions and review follow the reservation templates.</p>${link('Preview results','booking-results')}`,'Reuse calm result/detail/traveler/review patterns with organization context.','Preserve criteria and client reference across steps.'));else if(p.kind==='partner-reservations')a.push(S('Reservation filters & records',`<div class="form"><label>Find a reservation<input placeholder="Reference or client reference"></label></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Client</th><th>Travel dates</th><th>Status</th><th>Assigned team member</th></tr></thead><tbody><tr><td colspan="5">No reservation records yet.</td></tr></tbody></table></div>${link('Reservation detail layout','partner-reservation')}`,'Filterable operational table; only supported fields shown.','Stacked record summaries in implementation; table preview is horizontally contained.'));else if(p.kind==='partner-reservation')a.push(...reservationRecord(true));else if(p.kind==='partner-team')a.push(S('Team members & roles',`<h2>Who can access this workspace?</h2><div class="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th>Status</th></tr></thead><tbody><tr><td>Organization administrator</td><td>Administrator</td><td>Active account</td></tr></tbody></table></div><p>Member invitations and role changes appear only when the chosen account system supports organization permissions.</p>`,'Roles and membership; actions require real authorization rules.','Member and role pairs stack; permissions readable before changes.'));else a.push(S('Organization profile',`<form class="form"><label>Organization name<input></label><div class="pair"><label>Contact email<input type="email"></label><label>Preferred language<select><option>English</option><option>العربية</option><option>Türkçe</option></select></label></div><label>Business contact<input type="tel"></label><button class="submit">Save organization details</button><p class="form-message" role="status"></p></form>`,'Organization/contact preferences; billing and credit terms only if supplied by agreement/API.','Single-column editable profile with role-aware controls.'));return a;}
function stateSections(p){const x={notfound:['That route leads elsewhere.','The page could not be found. Keep exploring or get in touch.'],error:['A brief interruption.','We couldn’t load this service. Your entered criteria should stay available when you retry.'],loading:['Finding the next step.','Reservation data is loading. Avoid replacing this state with a fake confirmed booking.'],noresults:['Let’s try another route.','No matching options were returned for these criteria. Try different dates or contact the team.']}[p.kind];return [S('System state & recovery',`<div class="system"><span class="eyebrow">${p.kind==='notfound'?'404':'TRIP LINE'}</span><h1>${x[0]}</h1><p>${x[1]}</p><div class="actions">${link(p.kind==='notfound'?'Back to home':'Edit search',p.kind==='notfound'?'home':'booking-search')}${link('Ask for help')}</div></div>`,'One clear message with recovery and assistance; preserve entered context.','Short state with immediately reachable retry/back/help actions.')];}

function shell(p,sections){const partner=p.kind.startsWith('partner-')&&p.kind!=='partner-access',account=p.kind.startsWith('account-'),booking=p.group==='Future reservations';let content=sections.map((s,i)=>`<section class="${partner||account||booking?'portal-section':'section'} ${s.theme||''}" id="s${i}">${s.html}</section>`).join('');if(partner||account){const nav=partner?[['partner-overview','Overview'],['partner-search','Search'],['partner-reservations','Reservations'],['partner-team','Team'],['partner-settings','Settings']]:[['account-overview','Overview'],['account-trips','My reservations'],['account-profile','Profile']];return `${portalHeader(partner)}<div class="portal-shell"><aside class="portal-sidebar">${nav.map(([id,t])=>`<a href="#" data-page="${id}">${t}</a>`).join('')}</aside><main class="portal-body">${content}</main></div>`}if(booking)return `${portalHeader()}<main class="portal-body" style="background:var(--ivory);color:var(--deep);min-height:100vh">${content}</main>`;return `${header()}<main>${content}</main>${p.kind==='menu'?'':footer()}`}
function iframeScript(){return `<script>const cs=${JSON.stringify(countries)},media=${JSON.stringify(assets)};document.addEventListener('click',e=>{const a=e.target.closest('[data-page]');if(a){e.preventDefault();parent.postMessage({tripline:true,page:a.dataset.page},'*')}const pin=e.target.closest('[data-country]');if(pin){const c=cs.find(x=>x.id===pin.dataset.country);document.querySelectorAll('[data-country]').forEach(b=>{const active=b.dataset.country===c.id;b.classList.toggle('selected',active);b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});const box=document.getElementById('atlas-preview');if(box)box.innerHTML=(c.image?'<img class="atlas-photo" src="'+media[c.image]+'" alt="Illustrative Türkiye travel image">':'<div class="atlas-photo" style="background:#1f3e41;display:flex;align-items:end;padding:25px;font-size:24px">'+c.name+' · destination media to be supplied</div>')+'<span class="eyebrow">SELECTED DESTINATION</span><h3>'+c.name+'</h3><p>'+c.intro+'</p><div class="actions"><a class="link" href="#" data-page="country-'+c.id+'">Explore '+c.name+'</a><a class="link" href="#" data-page="contact">Ask about this destination</a></div>'}const toggle=e.target.closest('.atlas-toggle');if(toggle){const w=document.querySelector('.map-wrap');w.classList.toggle('visible');toggle.setAttribute('aria-expanded',w.classList.contains('visible'))}const f=e.target.closest('[data-feedback]');if(f){f.textContent=f.dataset.feedback}});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-country]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});document.addEventListener('submit',e=>{e.preventDefault();const m=e.target.querySelector('.form-message');if(m)m.textContent='Design preview: no data was sent or saved.'});window.addEventListener('message',e=>{if(e.data.tripline&&e.data.section!==undefined)document.getElementById('s'+e.data.section)?.scrollIntoView()});<\/script>`}
function render(){const p=PAGES.find(x=>x.id===current),ss=sectionsFor(p);document.getElementById('page-title').textContent=p.name;document.getElementById('page-route').textContent=p.route+(p.future?' · FUTURE INTEGRATION':' · DESIGN PROPOSAL');document.querySelectorAll('.page-picker').forEach(b=>b.setAttribute('aria-current',b.dataset.id===current?'page':'false'));document.getElementById('review-note').textContent=(p.future?'Future-phase design: inventory, prices, payment, cancellation, account roles and status depend on the external platform and chosen account system. ':'Public-site design: contextual inquiry and WhatsApp, with no invented booking availability. ')+(locale!=='en'?'Localized header and titles + '+(locale==='ar'?'RTL':'Turkish')+' structure preview. Full translated body copy remains a content deliverable. ':'')+(['home','about'].includes(p.id)?'Profile metrics, credentials and contacts require confirmation. ':'')+(p.kind==='country'&&!p.country.image?'Destination-specific photography is intentionally a labeled slot, not a mislabeled Türkiye image. ':'');document.getElementById('sections').innerHTML=ss.map((s,i)=>`<li><button data-section="${i}">${esc(s.name)}</button><span>PC: ${esc(s.desktop)}<br>Mobile: ${esc(s.mobile)}</span></li>`).join('')+(!p.future&&p.kind!=='menu'?'<li><button data-section="footer">Global footer</button><span>PC: four useful link columns. Mobile: 2-column links, direct WhatsApp, languages and legal access.</span></li>':'');document.getElementById('notes').innerHTML=`<strong>${ss.length} page sections + ${p.future?'utility shell':'global header'+(p.kind==='menu'?'':' and footer')}</strong><p>PC: 1280px composition, 7% page margins, large readable headings and deliberate editorial rows.</p><p>Mobile: 390px composition, 7% gutters, 44px control targets, 16px form text; no hover-only content.</p><p>Logo: bounded rendering of the original PDF lockup, not an AI replacement. The crop retains the source background; a clean production extraction still needs review.</p><p>Motion: native scrolling; one homepage signature sequence, quiet image/pin transitions elsewhere. Reduced motion shows complete content.</p><p>This is an inspectable layout proposal. Video, final photography and 3D choreography are not demonstrated by these layouts.</p>`;const doc=`<!doctype html><html lang="${locale}" dir="${locale==='ar'?'rtl':'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>${productCSS}</style></head><body>${shell(p,ss)}${iframeScript()}</body></html>`;document.getElementById('desktop').srcdoc=doc;document.getElementById('mobile').srcdoc=doc;document.getElementById('mobile').style.width='100%';sizeDesktop();}
function sizeDesktop(){const box=document.getElementById('desktop-canvas'),frame=document.getElementById('desktop');const scale=box.clientWidth/1280;frame.style.width='1280px';frame.style.height=(box.clientHeight/scale)+'px';frame.style.transform=`scale(${scale})`;frame.style.transformOrigin='top left'}
function navigate(id){if(current.startsWith('partner-')&&id.startsWith('booking-')&&PAGES.some(p=>p.id===id.replace('booking-','partner-')))id=id.replace('booking-','partner-');if(current.startsWith('partner-')&&id==='account-trip')id='partner-reservation';if(PAGES.some(p=>p.id===id)){current=id;render();document.querySelector('.toolbar').scrollIntoView({block:'start'})}}
document.getElementById('pages').innerHTML=[...new Set(PAGES.map(p=>p.group))].map(g=>`<div class="group-label">${g}</div>${PAGES.filter(p=>p.group===g).map(p=>`<button class="page-picker" data-id="${p.id}">${esc(p.name)}</button>`).join('')}`).join('');
document.addEventListener('click',e=>{const p=e.target.closest('.page-picker');if(p)navigate(p.dataset.id);const b=e.target.closest('[data-mode]');if(b){mode=b.dataset.mode;document.getElementById('review').className='review '+(mode==='both'?'':'only-'+mode);document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',x===b));sizeDesktop()}const s=e.target.closest('[data-section]');if(s){const val=s.dataset.section;if(val==='footer'){['desktop','mobile'].forEach(id=>document.getElementById(id).contentDocument?.getElementById('footer')?.scrollIntoView())}else ['desktop','mobile'].forEach(id=>document.getElementById(id).contentWindow.postMessage({tripline:true,section:Number(val)},'*'))}});
document.getElementById('locale').addEventListener('change',e=>{locale=e.target.value;render()});window.addEventListener('message',e=>{if(e.source===document.getElementById('desktop').contentWindow||e.source===document.getElementById('mobile').contentWindow){if(e.data.tripline&&e.data.page)navigate(e.data.page)}});window.addEventListener('resize',sizeDesktop);
// The companion CSS is embedded here by build_preview.py for offline portability.
productCSS=window.PRODUCT_CSS||'';render();
